{"content":"{
  "schema_version": "1.0",
  "manifest_type": "source_manifest_registry",
  "description_zh": "Source Bot 数据源请求与原始响应登记表，用于追踪每个数据源请求、响应时间、原始文件路径、状态和字段映射版本。",
  "records": [
    {
      "source_name": "string",
      "endpoint": "string|null",
      "request_started_at": "datetime|null",
      "response_received_at": "datetime|null",
      "provider_timestamp": "datetime|null",
      "raw_response_path": "string|null",
      "status": "pending|success|partial|failed|skipped",
      "error_message": "string|null",
      "field_mapping_version": "string"
    }
  ],
  "field_definitions": {
    "source_name": {
      "zh": "数据源名称",
      "required": true,
      "examples": [
        "GMGN",
        "Solana RPC",
        "DexScreener",
        "Jupiter Quote",
        "RugCheck",
        "CEX Label Library",
        "Internal Derived"
      ]
    },
    "endpoint": {
      "zh": "请求接口或接口标识",
      "required": true,
      "note_zh": "API key、token、签名参数必须脱敏；内部派生记录可使用 derived:<input_files>。"
    },
    "request_started_at": {
      "zh": "Source Bot 发起请求时间",
      "required": true,
      "time_schema_zh": "Source Bot 系统时间，ISO 8601 UTC；不得用 provider_timestamp 或 normalized_at 代替。"
    },
    "response_received_at": {
      "zh": "Source Bot 收到响应时间",
      "required": true,
      "time_schema_zh": "Source Bot 系统时间，ISO 8601 UTC；必须大于等于 request_started_at。"
    },
    "provider_timestamp": {
      "zh": "数据源提供方声明的数据时间",
      "required": false,
      "time_schema_zh": "优先记录 API 返回时间、链上 block_time、K线时间、quote/security 时间；源未返回时为 null，不得编造。"
    },
    "raw_response_path": {
      "zh": "原始响应保存路径",
      "required": false,
      "note_zh": "保存 raw response 时必须填写；未保存时为 null，并在对应质量报告中说明。"
    },
    "status": {
      "zh": "请求状态",
      "required": true,
      "allowed_values": [
        "pending",
        "success",
        "partial",
        "failed",
        "skipped"
      ]
    },
    "error_message": {
      "zh": "错误信息",
      "required": false,
      "note_zh": "status 为 failed 或 partial 时必须填写；成功时为 null。"
    },
    "field_mapping_version": {
      "zh": "字段映射版本",
      "required": true,
      "note_zh": "对应 docs/source_bot/source_to_structure_field_dictionary.md 或字段映射代码版本，例如 source_field_map_v1。"
    }
  },
  "time_integrity_rules": [
    "request_started_at <= response_received_at 必须成立。",
    "provider_timestamp 是源数据时间，不得与 request_started_at / response_received_at 混用。",
    "缺失 provider_timestamp 时只能写 null，不得用当前时间冒充。",
    "quote/security 类数据必须在业务 normalized 文件中继续保留 quote_time、quote_time_source、security_scan_time 等严格时间字段。"
  ]
}
","path":"shared/registry/source_manifest.json"}
